#!/usr/bin/env python3
"""
Round 152b (culprits), 4 October 2026. Needs round 151b.

Repaints the Woodlands basemap from real imagery.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 152b (4 October)\n\nNeeds round 151b. No tiles patch. No app.js?v= bump. Woodlands basemap redone again.\n\n- Owner on 151b: keep the mist, but deep earthy greens (not grey, not alien\n  green), an organic oil-painting look with no pattern at world views, the\n  sea and the mist over it wrong, too many greys; wants living earthy\n  contrast in colour and light, like Griffing's woodlands.\n- Land is now the cloud-free Sentinel-2 picture (EOX s2cloudless 2024,\n  CC BY-NC-SA, credited) re-painted pixel by pixel (woodpaint://,\n  woodPaintPixels): plants on a ramp from forest-shadow near-black through\n  deep earthy green to sunlit olive; bare ground umber to ochre; snow ivory;\n  an S-curve for contrast; then a soft Kuwahara (oil paint) filter. No\n  made-up noise anywhere: every variation is the Earth's own.\n- Warm golden light and deep olive-black shadow (Mapterhorn); mist on land\n  only, gone by 1,000 m; sea deep dark earthy blue-green by depth, no mist.\n  Ground and wet fills and the tone clouds gone (15 layers). Theme: bright.\n  Checked on sample satellite pictures (the sandbox cannot reach EOX), about\n  100 ms a square; not seen live.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round152b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 151b" not in h.read_text(encoding="utf-8"):
        sys.exit("round152b: round 151b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round152b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round152b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round152b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
